def get_ext(name):
    # returns extension with dot, lowercased
    idx = name.rfind(".")
    if idx <= 0:
        # for .hidden with no other dot, no ext; for no dot, no ext
        # check: ".hidden" -> no ext, "a.txt" -> .txt
        # os.path.splitext logic: if name starts with . and no other dot, no ext
        return ""
    return name[idx:].lower()

def is_archive(name):
    return get_ext(name) in ARCHIVE_EXTS
def is_audio(name):
    return get_ext(name) in AUDIO_EXTS
