    return tok[0]=='WORD' and tok[1].lower()==word.lower()

def split_clauses(tokens):
    # Returns dict with keys: select, from, where, groupby, orderby, limit, offset, into
    # tokens is list from lex_query
    # Normalize braces to parens: treat LBRACE as LPAREN, RBRACE as RPAREN for depth
    # Track depth
    # Find clause keywords at depth 0
    # Keywords: from, where, group by, order by, limit, offset, into
    # Note: 'select' at start is handled separately, not here.
    # Returns token slices for each clause (excluding keywords themselves, except groupby/orderby need to handle 'by')
    n=len(tokens)
    # Find positions
    # We'll scan and record indices of clause starts
    clauses={}
    # Helper to get token type/value lower
    def tok_lower(i):
        if tokens[i][0]=='WORD':
            return tokens[i][1].lower()
        elif tokens[i][0]=='OP':
            return tokens[i][1].lower()
        else:
            return None
    # Track depth
    depth=0
    # Record clause boundaries: list of (clause_name, index_of_keyword)
    bounds=[]  # (name, idx)
    i=0
