# ---------- Expression parsing ----------
# Token helpers for expression parser
class ExprParser:
    def __init__(self, tokens, aliases=None):
        # tokens: list of lex tokens for expression (e.g., SELECT part)
        # aliases: set of known aliases (for qualified detection)
        self.tokens = tokens
        self.pos = 0
        self.aliases = aliases or set()

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        t = self.peek()
        if t is not None:
            self.pos += 1
        return t

    def expect(self, typ=None, val=None):
        t = self.consume()
        if t is None:
            raise Exception("unexpected end")
        if typ and t[0]!=typ:
            raise Exception(f"expected {typ} got {t}")
        if val and t[1].lower()!=val.lower():
            raise Exception(f"expected {val} got {t}")
        return t

    def parse_expr_list(self):
        # Parse comma-separated expressions, also handling implicit separation by detecting adjacent exprs?
        # For SELECT, commas explicit, but also spaces implicit. Our tokens don't have spaces, so "name size" is two WORD tokens adjacent.
        # Our parser will parse first expr "name", then peek is WORD "size" (start of next expr) -> treat as separator.
        exprs=[]
        while self.pos < len(self.tokens):
            # skip commas
            if self.peek()[0]=='COMMA':
                self.consume()
                # allow trailing comma? continue
                if self.pos>=len(self.tokens):
                    break
                continue
            e=self.parse_expr()
            exprs.append(e)
            # after expr, check for comma or implicit
            if self.pos < len(self.tokens):
                if self.peek()[0]=='COMMA':
                    self.consume()
                    continue
                # if next token can start expr and previous expr ended, treat as implicit comma (do not consume, just continue loop)
                # But need to avoid infinite loop: if next token is operator that continues expr, parse_expr would have consumed it.
                # So if next token is WORD, STRING, LPAREN, etc., it's next expr.
                # We'll just continue (parse next expr in next iteration) without requiring comma.
                # However, need to ensure we don't treat trailing tokens that are actually errors as next expr?
                # For now, continue.
                pass
        return exprs

    def parse_expr(self):
        return self.parse_add()

    def parse_add(self):
        left=self.parse_mul()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1] in ('+','-'):
                op=self.consume()[1]
                right=self.parse_mul()
                left=('binop',op,left,right)
            else:
                break
        return left

    def parse_mul(self):
        left=self.parse_unary()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1] in ('*','/','%'):
                op=self.consume()[1]
                right=self.parse_unary()
                left=('binop',op,left,right)
            else:
                break
        return left

    def parse_unary(self):
        t=self.peek()
        if t and t[0]=='OP' and t[1] in ('+','-'):
            op=self.consume()[1]
            e=self.parse_unary()
            return ('unary',op,e)
        return self.parse_primary()

    def parse_primary(self):
        t=self.peek()
        if t is None:
            raise Exception("expected expr")
        if t[0] in ('LPAREN','LBRACE'):
            self.consume()
            e=self.parse_expr()
            # expect matching R
            r=self.consume()
            if r is None or r[0] not in ('RPAREN','RBRACE'):
                raise Exception("expected )")
            return e
        if t[0]=='OP' and t[1]=='*':
            self.consume()
            return ('star',)
        if t[0]=='STRING':
            self.consume()
            # t is ('STRING', content, quote) - 3 elements
            content=t[1] if len(t)>1 else ""
            return ('literal',content)
        if t[0]=='WORD':
            word=self.consume()[1]
            # check for function call: next is LPAREN/LBRACE?
            nxt=self.peek()
            if nxt and nxt[0] in ('LPAREN','LBRACE'):
                # function
                self.consume() # '('
                args=[]
                # handle * special? e.g., count(*)
                # check for empty args? e.g., now() with no args
                # parse args until matching R
                # Need to handle that args are comma-separated exprs, but * is special
                # If next is RPARAN -> no args
                if self.peek() and self.peek()[0] in ('RPAREN','RBRACE'):
                    self.consume()
                    return ('func',word.lower(),args)
                while True:
                    # check for *?
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='*':
                        self.consume()
                        args.append(('star',))
                    else:
                        # parse expr (could be literal, column, etc.)
                        # But need to handle that args may contain strings with commas? Already lexed, commas are separate, so fine.
                        args.append(self.parse_expr())
                    # after arg, expect comma or R
                    nxt2=self.peek()
                    if nxt2 and nxt2[0]=='COMMA':
                        self.consume()
