                    elif nxt2 and nxt2[0] in ('RPAREN','RBRACE'):
                        self.consume()
                        break
                    else:
                        raise Exception("expected , or ) in func")
                return ('func',word.lower(),args)
            else:
                # check for qualified? next is DOT? Actually DOT is OP '.'; need to handle WORD DOT WORD
                if nxt and nxt[0]=='OP' and nxt[1]=='.':
                    # consume dot and next word
                    self.consume() # dot
                    nxt2=self.consume()
                    if nxt2 is None or nxt2[0]!='WORD':
                        raise Exception("expected word after .")
                    # qualified: alias.column
                    return ('col',nxt2[1].lower(),word.lower())  # (col, column, alias)
                else:
                    # Check if word is numeric? e.g., "123", "1k", "1.5"
                    # Try to parse as number? For now, return as word - evaluator will decide if column or literal
                    # If word is numeric literal (digits), treat as literal number?
                    # We'll treat as ('word', word) and let evaluator decide: if known column/function without parens, it's column; else literal.
                    return ('word',word)
        if t[0]=='OP' and t[1] in ('+','-','*','/','%'):
            # should have been handled? But * as star already? For safety
            raise Exception(f"unexpected op {t}")
        raise Exception(f"unexpected token {t}")

def parse_select_tokens(tokens, aliases=None):
    if not tokens:
        return None, "no selector"
    # Handle * expansion? Actually * as single token should be parsed as star, then expanded later.
    # Use ExprParser
    try:
        p=ExprParser(tokens, aliases)
        exprs=p.parse_expr_list()
        if p.pos != len(tokens):
            return None, "trailing"
        if not exprs:
            return None, "no selector"
        return exprs, None
    except Exception as e:
